let inlineEditor=null;const inlineDrafts=new Map();
const inlineView=()=>tab+'|'+(tab==='team'?tc.v:tab==='agenda'&&vm==='roster'?'roster':'');
function suspendInline(){if(inlineEditor){if(inlineEditor.node.querySelector('#fc'))inlineEditor.shiftId=editingShift;inlineEditor.node.remove();inlineDrafts.set(inlineEditor.key||inlineEditor.view,inlineEditor);inlineEditor=null}}
function dismissInline(){inlineEditor?.node.remove();inlineDrafts.delete(inlineEditor?.key||inlineView());inlineEditor=null;draftNotice()}
function draftNotice(){document.querySelector('#draft-notice')?.remove();const drafts=[...inlineDrafts.values()].filter(e=>e!==inlineEditor);if(!drafts.length)return;const node=document.createElement('div');node.id='draft-notice';node.className='draft-notice';node.setAttribute('role','status');node.innerHTML=`<span>${T2('Unsaved draft','پیش‌نویس ذخیره نشده')} · ${drafts.length}</span><button class="text-button" onclick="resumeDraft()">${T2('Continue editing','ادامهٔ ویرایش')}</button>`;$('#v').prepend(node)}
function resumeDraft(){const draft=[...inlineDrafts.values()].find(e=>e!==inlineEditor);if(!draft)return;parkInline();inlineDrafts.delete(draft.key||draft.view);delete draft.key;inlineDrafts.set(draft.view,draft);const [dest,view]=draft.view.split('|');tab=dest;if(dest==='team')tc.v=view;if(dest==='agenda')vm=view==='roster'?'roster':vm==='roster'?'month':vm;render();draft.node.open=true;draft.node.scrollIntoView?.({block:'start'});draft.node.querySelector('summary').focus?.({preventScroll:true});draftNotice();if(tour.active)renderTour()}
function mountInline(editor){let anchor;
 if(typeof editor.anchor==='object'){const a=editor.anchor;anchor=a.type==='colleague'?[...document.querySelectorAll('.colleague-card')].find(n=>n.dataset.mid===a.mid):[...document.querySelectorAll('.swap-option')].find(n=>n.dataset.hid===a.hid&&n.dataset.mid===a.mid&&(!a.date||n.dataset.date===a.date))}
 else anchor=editor.anchor&&$(editor.anchor);
 if(anchor){let closed;while(closed=anchor.parentElement?.closest('details:not([open])'))anchor=closed;anchor.insertAdjacentElement('afterend',editor.node);}else $('#v').prepend(editor.node);
}
function parkInline(){suspendInline();const previous=inlineDrafts.get(inlineView());if(previous){inlineDrafts.delete(inlineView());previous.key=previous.view+'|draft'+(++draftSequence);inlineDrafts.set(previous.key,previous)}}
let draftSequence=0;
function showInline(html,anchor=''){parkInline();const modal=$('#dlg');if(modal.open)modal.close();$('#change-feedback').hidden=true;const node=document.createElement('details');node.className='c inline-editor';node.id='inline-editor';node.open=true;node.innerHTML=`<summary><span class="inline-title"></span><small>${T2('Unsaved','ذخیره نشده')}</small></summary><div class="inline-body">${html}</div>`;node.querySelector('.inline-title').textContent=node.querySelector('h3')?.textContent||T2('Edit','ویرایش');inlineEditor={node,anchor,view:inlineView()};inlineDrafts.set(inlineView(),inlineEditor);mountInline(inlineEditor);autoDir(node);tr(node);isolateMixed(node);node.querySelectorAll('button').forEach(b=>{if(b.getAttribute('onclick')?.trim()==='closeDialog()')b.classList.add('cancel-button')});if(tab==='agenda'&&vm==='month'&&node.querySelector('#fc')){const back=document.createElement('button');back.className='text-button calendar-return';back.textContent=T2('Back to calendar','برگشت به تقویم');back.onclick=()=>returnToMonth();node.querySelector('.inline-body').prepend(back)}node.querySelector('summary').focus?.({preventScroll:true});gentleScrollTo(node);draftNotice();if(tour.active)renderTour()}
