function hdr(){const feedback=$('#change-feedback');autoDir($('#v'));const L=NAV.find(n=>n[0]===tab)[2];$('#hd').innerHTML=`<div><b>${L}</b><span class="header-date mu">${dayLabel(iso(Date.now()))}</span></div>${['today','agenda','team'].includes(tab)?`<div class="header-controls">${tab==='today'?'':undoButton()}<button class="icon-button header-add ${tab==='team'||!S.shifts.length?'hidden':''}" onclick="addSchedule()" aria-label="${T2('Add schedule','افزودن برنامه')}">${T2('+ Add roster','+ افزودن برنامه')}</button><button class="icon-button" onclick="go('set')" aria-label="${T2('Settings','تنظیمات')}">⚙</button></div>`:`<div class="header-controls">${undoButton()}<button class="icon-button" onclick="go(${jsArg(tab==='trip'?travel.returnTab:tab==='places'?'set':tab==='roster'?roster.returnTab:'today')})">${T2('Back','برگشت')}</button></div>`}`;if(feedback)$('#hd').append(feedback);const f=document.querySelector('.fab');f.style.display='none';f.innerHTML=T2('+ Add schedule','+ افزودن برنامه')}
function addSchedule(){if(importDrafts.pending.has('photo')){go('scan');return}if(!S.wps.length)return go('setup');if(!sc.cells&&!sc.pick&&!sc.align&&!sc.dateCheck){sc.method='';sc.entryDate=''}go('scan')}

