function groupedCodes(w){const off=w.codes.filter(c=>c.type==='off'),rest=w.codes.filter(c=>c.type!=='off').map(c=>({...c,aliases:[...(c.aliases||[])]}));if(off.length){const c=off.find(c=>c.code==='-')||off[0];rest.push({...c,code:offCode(w),aliases:[...new Set(off.flatMap(x=>[x.code,...(x.aliases||[])]).concat(['OFF','*','-']))].filter(x=>x!==offCode(w)&&!rest.some(c=>c.code===x||(c.aliases||[]).includes(x)))})}return rest}
function codeEditorRows(){return wpDraft.map((c,i)=>`<details class="code-editor" data-index="${i}"><summary><bdi dir="ltr">${esc(c.code||'?')}</bdi><span>${esc(codeStatusLabel(c))}</span><small>${c.type==='off'?T2('Off','off'):c.type==='leave'?T2('Leave','مرخصی'):esc(c.start+' – '+c.end)}</small></summary><div class="code-fields"><label>${T2('Symbol in your roster','علامت در برنامه')}<input class="code-value" dir="auto" onchange="syncHoursDayCodes()" value="${esc(c.code)}" autocapitalize="off"></label><label>${T2('Meaning','معنی')}<input class="code-label" value="${esc(codeStatusLabel(c))}"></label><div class="code-times" ${c.type!=='work'?'hidden':''}><label>${T2('Start','شروع')}<input class="code-start" type="time" value="${esc(c.start||'07:30')}"></label><label>${T2('End','پایان')}<input class="code-end" type="time" value="${esc(c.end==='24:00'?'00:00':c.end||'14:30')}"></label></div><details class="code-advanced"><summary>${T2('Shift type, aliases & hours','نوع، علامت‌های هم‌معنی و ساعت')}</summary><label>${T2('Kind','نوع')}<select class="code-type" onchange="this.closest('.code-editor').querySelector('.code-times').hidden=this.value!=='work';refreshHoursRole(this)">${['work','off','leave'].map(t=>`<option value="${t}" ${c.type===t?'selected':''}>${t==='work'?T2('Work','شیفت'):t==='off'?T2('Off','off'):T2('Leave','مرخصی')}</option>`).join('')}</select></label><label>${T2('Other symbols with this meaning','علامت‌های هم‌معنی')}<input class="code-alias" dir="auto" placeholder="${T2('Separate with commas','با ویرگول جدا کنید')}" value="${esc((c.aliases||[]).join(', '))}"></label>${hoursRoleEditor(c)}</details></div><button class="text-button danger-text" onclick="removeCode(${i})">${T2('Remove symbol','حذف علامت')}</button></details>`).join('')}
function collectCodes(){return [...$('#code-rows').querySelectorAll('.code-editor')].map(r=>({code:nrm(r.querySelector('.code-value').value.trim()),label:r.querySelector('.code-label').value.trim(),type:r.querySelector('.code-type').value,hoursRole:r.querySelector('.code-hours').value,start:r.querySelector('.code-start').value,end:r.querySelector('.code-end').value,aliases:nrm(r.querySelector('.code-alias').value).split(/[,،]/).map(x=>x.trim()).filter(Boolean)}))}
function appendCode(){wpDraft=collectCodes();wpDraft.push({code:'',label:'',type:'work',start:'07:30',end:'14:30',aliases:[]});$('#code-rows').innerHTML=codeEditorRows();$('#code-rows').lastElementChild.open=true;$('#code-rows').lastElementChild.querySelector('input').focus();syncHoursDayCodes()}
