function calendarFilter(){if(S.wps.length<2)return '';return `<select class="calendar-workplace-filter" aria-label="${T2('Calendar workplace','محل کار در تقویم')}" onchange="calendarWorkplace=this.value;render()"><option value="">${T2('All workplaces','همهٔ محل‌های کار')}</option>${S.wps.map(w=>`<option value="${esc(w.id)}" ${calendarWorkplace===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select>`}
