function openTrip(){travel.returnTab=['today','agenda','team'].includes(tab)?tab:'today';travel.from=travel.from||iso(Date.now());travel.unit=travel.unit||'days';travel.time=travel.time||'00:00';travel.searched=false;travel.checkChanges=false;travel.error='';go('trip')}
function setPlannerUnit(unit){const from=dGet('trip-from'),time=$('#planner-time')?.value;if(from)travel.from=from;if(time)travel.time=time;const amount=+nrm($('#planner-amount').value);if(amount>0){if(unit==='days')travel.days=amount;else travel.hours=amount}travel.unit=unit;travel.searched=false;render()}
function changeTrip(){const from=dGet('trip-from'),amount=+nrm($('#planner-amount').value),unit=$('#planner-unit').value,time=$('#planner-time').value;if(!from||!Number.isFinite(amount)||amount<.5||amount>(unit==='days'?30:720)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)){travel.error=T2('Enter a valid duration, date and time.','مدت، تاریخ و ساعت را درست وارد کن.');const error=$('#planner-error');if(error){error.textContent=travel.error;error.hidden=false}return}travel.from=from;travel.time=time;travel.unit=unit;if(unit==='days')travel.days=amount;else travel.hours=amount;travel.error='';travel.searched=true;travel.checkChanges=false;render()}
function tripCalc({days,hours,minutes,from=travel.from||iso(Date.now()),time='00:00',includeChanges=true}={}){
 const needed=minutes!==undefined?minutes*6e4:hours!==undefined?hours*3600000:days!==undefined?days*DAY:plannerMinutes()*6e4;
 const start=Math.max(at(from,time),Math.ceil(Date.now()/6e4)*6e4),base=freeWindows(0,{start}),swaps=[],covers=new Map(),blockedSwaps=[];if(!Number.isFinite(needed)||needed<=0)return{...base,ready:[],swaps,needed,blockedSwaps};const ready=base.slots.filter(([a,b])=>b-a>=needed),minimumGain=Math.min(12*3600000,needed);
 if(!includeChanges)return{...base,ready,swaps,needed,blockedSwaps};
 for(const h of S.shifts){if(h.review||!h.segs.length||Math.min(...h.segs.map(g=>g.s))<start||!h.segs.some(g=>g.e>start&&g.s<base.end))continue;const altered=freeWindows(0,{start,end:base.end,excludeShift:h.id}),gap=altered.slots.filter(([a,b])=>b-a>=needed&&h.segs.some(g=>g.s<b&&g.e>a)).sort((a,b)=>(b[1]-b[0])-(a[1]-a[0]))[0];if(!gap)continue;
 const previous=Math.max(0,...base.slots.map(([a,b])=>Math.max(0,Math.min(b,gap[1])-Math.max(a,gap[0])))),gain=gap[1]-gap[0]-previous;if(gain<minimumGain)continue;const cover=coverCalc(wp(h.wp),[h.id]).rows[0];covers.set(h.id,cover);blockedSwaps.push(...(cover?.conflicts||[]).map(x=>({...x,h})));swaps.push({h,gap,gain,previous,people:[...(cover?.free||[]),...(cover?.ext||[])].filter(x=>(!x.f.p||x.f.p.g>=S.gap)&&(!x.f.n||x.f.n.g>=S.gap)),unknown:cover?.unk.length||0})}
 const reciprocal=[],windows=new Map();for(const proposal of swaps){const h=proposal.h,row=covers.get(h.id);for(const x of row?.swap||[]){const cacheKey=h.id+'|'+x.date;if(!windows.has(cacheKey)){const changed=freeWindows(0,{start,end:base.end,excludeShift:h.id,extraSegs:x.ownChanges[x.date].segs}),gap=changed.slots.filter(([a,b])=>b-a>=needed&&h.segs.some(g=>g.s<b&&g.e>a)).sort((a,b)=>(b[1]-b[0])-(a[1]-a[0]))[0];if(!gap){windows.set(cacheKey,null);continue}const previous=Math.max(0,...base.slots.map(([a,b])=>Math.max(0,Math.min(b,gap[1])-Math.max(a,gap[0])))),gain=gap[1]-gap[0]-previous;windows.set(cacheKey,gain<minimumGain?null:{gap,previous,gain})}const result=windows.get(cacheKey);if(!result)continue;const key=cacheKey+'|'+result.gap.join('|'),existing=reciprocal.find(r=>r.key===key);if(existing)existing.people.push(x);else reciprocal.push({key,kind:'exchange',h,...result,people:[x],returnDate:x.date,unknown:0})}}
 swaps.push(...reciprocal);swaps.sort((a,b)=>Number(b.people.length>0)-Number(a.people.length>0)||(b.gap[1]-b.gap[0])-(a.gap[1]-a.gap[0]));return{...base,ready,swaps,needed,blockedSwaps};
}
function openTripSwap(id){const h=S.shifts.find(x=>x.id===id);if(!h)return;tc.wp=h.wp;tc.dates=[id];go('team');coverGo()}
function openTripExchange(hid,mid,date){const h=S.shifts.find(h=>h.id===hid);if(!h)return;tc.wp=h.wp;tc.dates=[hid];go('team');coverGo();exchangePreview(hid,mid,date)}
function bookTrip(a,b){showInline(`<h3>${T2('Save this time','ثبت برنامه در این بازه')}</h3><label for="trip-title">${T2('Name','عنوان برنامه')}<input id="trip-title" value="${T2('Free time','وقت آزاد')}"></label><div class="compact-window">${windowRange(a,b)}</div><button class="p" onclick="saveTrip(${a},${b})">Save</button><button class="p s" onclick="closeDialog()">${T2('Cancel','لغو')}</button>` ,'.planner-controls')}
async function saveTrip(a,b){if(!Number.isFinite(a)||!Number.isFinite(b)||b<=a)return;const available=freeWindows(0,{start:a,end:b}).slots.some(([s,e])=>s<=a&&e>=b);if(!available){const conflicts=personalScheduleConflicts([{s:a,e:b}],{rest:false});return alert(T2('This period is no longer free. ','این بازه دیگر آزاد نیست. ')+(conflicts.length?conflicts.map(scheduleConflictText).join('\n'):T2('Complete or review the rosters.','برنامهٔ محل‌های کار را کامل یا بررسی کن.')))}const change=beginChange('Personal time','وقت شخصی',['events']);S.events.push({id:'trip'+Date.now()+Math.random().toString(36).slice(2,7),title:$('#trip-title').value.trim()||T2('Free time','وقت آزاد'),type:'custom',s:a,e:b});if(!await commitChange(change))return;closeDialog();sel=iso(a);cm=mfirst(new Date(a));go('agenda')}
V.trip=()=>{travel.unit=travel.unit||'days';const minutes=plannerMinutes(),r=travel.searched?tripCalc({minutes,from:travel.from,time:travel.time||'00:00',includeChanges:!!travel.checkChanges}):null;const controls=`<section class="c trip-controls planner-controls"><label class="planner-duration"><span>${T2('How much time do you need?','چقدر وقت می‌خوای؟')}</span><div class="planner-amount"><input id="planner-amount" type="number" inputmode="decimal" min="0.5" max="${travel.unit==='days'?30:720}" step="any" aria-label="${T2('Duration','مدت')}" value="${travel.unit==='days'?travel.days:travel.hours||S.fh||2}"><select id="planner-unit" aria-label="${T2('Duration unit','واحد مدت')}" onchange="setPlannerUnit(this.value)"><option value="hours" ${travel.unit==='hours'?'selected':''}>${T2('Hours','ساعت')}</option><option value="days" ${travel.unit==='days'?'selected':''}>${T2('Days (24 hours)','روز (۲۴ ساعت)')}</option></select></div></label><details class="flow-more planner-when"><summary>${T2('Choose a start date or time','از روز یا ساعت مشخصی می‌خوای؟')}</summary><div class="planner-start"><label><span>${T2('From date','از تاریخ')}</span>${dField('trip-from',travel.from||iso(Date.now()))}</label><label><span>${T2('From time','از ساعت')}</span><input id="planner-time" type="time" value="${travel.time||'00:00'}"></label></div></details><button class="p" onclick="changeTrip()">${T2('Find free time','پیدا کردن وقت آزاد')}</button><p id="planner-error" class="scan-error" role="alert" ${travel.error?'':'hidden'}>${esc(travel.error||'')}</p></section><p class="planner-scope">${T2('Checks all saved workplaces and personal plans','بررسی همهٔ شیفت‌ها و برنامه‌های شخصی ثبت‌شده')}</p>`;
 if(!r)return controls;const card=([a,b])=>`<section class="c trip-card"><div class="row"><b>${gapDuration(a,b)}</b><span class="trip-status">${T2('No shift change','بدون تغییر شیفت')}</span></div><div class="compact-window">${windowRange(a,b)}</div><div class="plan-save-range"><small>${T2('Your plan will be saved for','زمان ثبت برنامهٔ شما')}</small><div class="compact-window">${windowRange(a,a+r.needed)}</div></div><button class="p s" onclick="bookTrip(${a},${a+r.needed})">${T2('Save a plan here','ثبت برنامه در این بازه')}</button></section>`;
 return controls+coverageNeedsV(r.start,r.end)+`<h1>${T2('FREE PERIODS','وقت‌های آزاد')}</h1>`+(r.ready.length?r.ready.map(card).join(''):`<div class="c mu">${T2('No confirmed free period matches this duration.','برای این مدت، وقت آزاد تأییدشده پیدا نشد.')}</div>`)+`<details class="flow-more trip-change-options"><summary>${T2('Also check shift changes','با تغییر شیفت هم بررسی کنیم؟')}</summary>`+(!travel.checkChanges?`<button class="p s planner-changes" onclick="travel.checkChanges=true;render()">${T2('Find options with a shift change','پیدا کردن بازه با تغییر شیفت')}</button>`:r.swaps.length?r.swaps.map(x=>`<section class="c trip-card"><div class="row"><b>${gapDuration(...x.gap)}</b><span class="trip-status tentative">${T2('If agreed','در صورت توافق')}</span></div><div class="compact-window">${windowRange(...x.gap)}</div><p class="trip-change">${x.kind==='exchange'?T2('Exchange','تعویض دوطرفه'):T2('Hand over','واگذاری')} ${codeHTML(x.h.text)} · ${dateHTML(x.h.date)} · ${bidi(wp(x.h.wp).name)}${x.returnDate?`<br>${T2('Your return shift','شیفت برگشتی شما')}: ${dateHTML(x.returnDate)}`:''}</p><div class="trip-people"><p>${x.people.length?x.people.map(p=>colleagueLabel(p.m)).join('، '):T2('No confirmed colleague yet.','هنوز جایگزین تأییدشده‌ای پیدا نشد.')}</p></div>${x.kind==='exchange'?x.people.map(person=>`<button class="p s" onclick="openTripExchange(${jsArg(x.h.id)},${jsArg(person.m.id)},${jsArg(x.returnDate)})">${T2('Preview with ','پیش‌نمایش با ')}${colleagueLabel(person.m)}</button>`).join(''):`<button class="p s" onclick="openTripSwap(${jsArg(x.h.id)})">${T2('Check this change','بررسی این تغییر')}</button>`}</section>`).join(''):`<div class="c mu">${T2('No suitable single-shift change found.','با تغییر یک شیفت هم بازهٔ مناسبی پیدا نشد.')}</div>`)+
 (r.blockedSwaps.length?`<details class="blocked-options"><summary>${T2('Exchanges with conflicts','تعویض‌های دارای تداخل')}</summary>${r.blockedSwaps.map(x=>`<p>${colleagueLabel(x.m)} · ${dateHTML(x.date)}<br>${esc(swapReason(x))}</p>`).join('')}</details>`:'')+
 `</details>`+(r.missingWorkplaces?.length||r.unknownDays?`<p class="trip-footnote">${r.missingWorkplaces?.length?T2('Roster missing or expired: ','برنامه ثبت نشده یا قدیمی است: ')+r.missingWorkplaces.map(n=>bidi(n)).join('، '):''}${r.unknownDays?` ${r.unknownDays} ${T2('dates need roster review.','روز نیاز به بررسی برنامه دارد.')}`:''}</p>`:'');
};

function addEvent(id=''){const event=S.events.find(e=>e.id===id),start=event?.s??at(sel||iso(Date.now()),'10:00'),end=event?.e??start+3600000;showInline(`<h3>${event?T2('Edit personal event','ویرایش برنامهٔ شخصی'):T2('Personal event','برنامهٔ شخصی')}</h3><label>${T2('Title','عنوان')}<input id="et" value="${esc(event?.title||'')}" placeholder="${T2('e.g. appointment or a trip','مثلاً قرار ملاقات یا سفر')}"></label><label>${T2('Type','نوع')}<select id="ety">${[['appointment',T2('Appointment','قرار ملاقات')],['gym',T2('Exercise','ورزش')],['university',T2('University','دانشگاه')],['trip',T2('Trip','سفر')],['task',T2('Task','کار شخصی')],['custom',T2('Other','سایر')]].map(([key,label])=>`<option value="${key}" ${event?.type===key?'selected':''}>${label}</option>`).join('')}</select></label><div class="shift-fields"><label>${T2('Start date','تاریخ شروع')}${dField('ed',iso(start))}</label><label>${T2('End date','تاریخ پایان')}${dField('eed',iso(end))}</label><label>${T2('Start','شروع')}<input id="es" type="time" value="${localTime(start)}"></label><label>${T2('End','پایان')}<input id="ee" type="time" value="${localTime(end)}"></label></div><div class="dialog-actions"><button class="p" onclick="saveEvent(${esc(JSON.stringify(id))})">Save</button><button class="p s" onclick="closeDialog()">${T2('Cancel','لغو')}</button></div>${event?`<button class="text-button danger-text" onclick="delEvent(${esc(JSON.stringify(id))})">${T2('Delete event','حذف برنامه')}</button>`:''}`,'.calendar-panel')}
const localTime=ms=>{const d=new Date(ms);return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')};
const editEvent=id=>addEvent(id);
async function saveEvent(id=''){const d=dGet('ed'),endDate=dGet('eed'),start=$('#es').value,end=$('#ee').value,title=$('#et').value.trim();if(!d||!endDate||!start||!end||!title)return alert(T2('Enter a title, dates and times.','عنوان، تاریخ و ساعت را وارد کنید.'));const a=at(d,start),b=at(endDate,end);if(b<=a)return alert(T2('The end must be after the start.','پایان برنامه باید بعد از شروع آن باشد.'));const existing=id&&S.events.find(e=>e.id===id);if(id&&!existing)return alert(T2('This event was removed.','این برنامه حذف شده است.'));const change=beginChange('Personal event','برنامهٔ شخصی',['events']),event={id:id||'e'+Date.now()+Math.random().toString(36).slice(2,7),title,type:$('#ety').value,s:a,e:b};if(existing)Object.assign(existing,event);else S.events.push(event);if(!await commitChange(change))return;closeDialog();sel=iso(a);cm=mfirst(new Date(a));if(tab==='agenda')daySelected=true;render();$('#selected-day')?.scrollIntoView?.({block:'start',behavior:'instant'})}

async function delEvent(id){if(confirm(T2('Delete this event?','این برنامهٔ شخصی حذف شود؟'))){const change=beginChange('Event removal','حذف برنامهٔ شخصی',['events']);S.events=S.events.filter(e=>e.id!==id);if(!await commitChange(change))return;closeDialog();render()}}
V.agenda=()=>{if(!['month','roster'].includes(vm))vm='month';return `<div class="calendar-navigation"><div class="seg" role="group" aria-label="${T2('Calendar view','نمای تقویم')}">${vbtn('month','Month')}<button class="${vm==='roster'?'on':''}" aria-pressed="${vm==='roster'}" onclick="openRoster()" title="${T2('Roster table','جدول شیفت‌ها')}">${T2('Roster table','جدول شیفت‌ها')}</button></div></div>${vm==='roster'?'':`<div class="calendar-actions"><button class="calendar-trip" onclick="openTrip()"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3 11 18-7-7 18-3-8-8-3Zm8 3 5-5" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round" stroke-linecap="round"/></svg><span>${T2('Free time & trips','وقت آزاد و سفر')}</span><span aria-hidden="true">↗</span></button></div>`}`+(vm==='roster'?V.roster():monthV())};
/* Each photo read owns a generation. Canceled work cannot publish late results. */
let scanGeneration=0;const scanWaiters=new Set();
function scanCheck(run){if(run!==scanGeneration)throw Error('Scan cancelled')}
function scanAwait(promise,run=scanGeneration,ms=60000){return new Promise((resolve,reject)=>{let timer;const stop=()=>{clearTimeout(timer);scanWaiters.delete(cancel)},cancel=()=>{stop();reject(Error('Scan cancelled'))};scanWaiters.add(cancel);timer=setTimeout(()=>{if(run===scanGeneration)cancelPhotoScan(T2('Reading took too long. Try another photo or straighten this one.','خواندن طول کشید؛ عکس دیگری انتخاب کن یا همین عکس را صاف کن.'));else cancel()},ms);Promise.resolve(promise).then(value=>{stop();try{scanCheck(run);resolve(value)}catch(e){reject(e)}},error=>{stop();reject(error)})})}
function cancelPhotoScan(message=''){++scanGeneration;for(const cancel of [...scanWaiters])cancel();const workers=['wk','fasWk','expertWk'].map(key=>{const w=sc[key];sc[key]=null;return w});for(const w of workers)try{Promise.resolve(w?.terminate()).catch(()=>{})}catch{}sc.wkLang=null;sc.busy=false;sc.pick=false;sc.cells=null;sc.rows=[];sc.pages=[];sc.align=null;sc.dateCheck=null;sc.columnPick=null;sc.photoRowPick=null;sc.continueReadRow=null;sc.method='photo';sc.msg=message;render()}
function scanExitV(){return `<div class="scan-exit"><button class="p s" onclick="cancelPhotoScan()">${T2('Back / stop reading','برگشت / توقف خواندن')}</button><label class="p s">${T2('Choose another photo','انتخاب عکس دیگر')}<input type="file" accept="image/*" hidden onchange="scanFile(this.files);this.value=''"></label></div>`}
function repairFailedPhoto(){if(!sc.failedSource)return;sc.pages=[{source:sc.failedSource,cv:sc.failedSource,rows:[]}];sc.align={pi:0,cv:sc.failedSource,points:[]};sc.msg='';render()}
async function scanGrid(cv,threshold,run){if(typeof Worker==='undefined')return gridOf(cv,threshold);const blob=new Blob([`const gridScan=${gridScan.toString()};onmessage=e=>{try{const {data,w,h,threshold}=e.data;postMessage({grid:gridScan(data,w,h,threshold)})}catch(e){postMessage({error:e.message})}}`],{type:'application/javascript'}),url=URL.createObjectURL(blob);let worker;try{worker=new Worker(url);return await scanAwait(new Promise((resolve,reject)=>{worker.onmessage=e=>e.data.error?reject(Error(e.data.error)):resolve(e.data.grid);worker.onerror=()=>reject(Error('Grid detection failed'));worker.postMessage({data:cv.getContext('2d').getImageData(0,0,cv.width,cv.height).data,w:cv.width,h:cv.height,threshold})}),run,45000)}finally{worker?.terminate();URL.revokeObjectURL(url)}}
function openCalendarDate(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return;const old=inlineEditor;if(old?.node.querySelector('#fc')){const input=old.node.querySelector('#fc'),h=S.shifts.find(h=>h.id===old.shiftId),unchanged=h&&input.value===canonicalShift(wp(h.wp),h.text)&&dGet('fd')===h.date&&$('#fw')?.value===h.wp;if(unchanged)dismissInline();else parkInline()}else suspendInline();sel=date;daySelected=true;render();const hs=S.shifts.filter(h=>h.date===date&&(!calendarWorkplace||h.wp===calendarWorkplace));if(hs.length===1)editShift(hs[0].id);else if(!hs.length&&S.wps.length===1)addSelectedDayShift();else gentleScrollTo($('#selected-day'))}
