function moreOptions(body,key,label=T2('More options','گزینه‌های بیشتر')){return `<details class="flow-more" data-keep-open="${esc(key)}"><summary>${label}</summary><div class="flow-more-body">${body}</div></details>`}
function simpleReviewQuestion(checking,count){return checking?T2('I’m not sure about a few shifts. Let’s check them together.','چندتا از شیفت‌هات رو مطمئن نیستم درست خونده باشم؛ بیا با هم بررسی کنیم.'):count?T2('Some shifts are still unclear. Keep them for later, or check them now.','چندتا شیفت هنوز نامشخصه؛ می‌تونی بعداً بررسی‌شون کنی یا الان برگردی سراغشون.'):T2('Your roster is ready. Shall we save it?','برنامه آماده‌ست؛ ثبتش کنیم؟')}
function syncSimpleReview(){const root=$('.simple-review');if(!root)return;const count=scanPendingIndices().length,checking=(!sc.reviewFinish&&count>0)||!!sc.reviewEditing;root.classList.toggle('checking',checking);root.classList.toggle('finishing',!checking);$('#scan-question').textContent=simpleReviewQuestion(checking,count);if(!checking)root.querySelector('.review-more').open=false;renderImportProgress();queueImportDrafts()}
