function offlineScannerV(){return `<section class="offline-scanner"><b>${T2('Scan without internet','اسکن بدون اینترنت')}</b><p>${T2('Download the scanner once (about 14 MB). Your photos stay on this device.','اسکنر را یک‌بار آماده کنید (حدود ۱۴ مگابایت). عکس‌ها روی همین دستگاه می‌مانند.')}</p><p id="scanner-offline-status" class="scanner-status${scannerOffline.ready?' ready':''}" role="status" aria-live="polite">${scannerOfflineText()}</p><button id="scanner-offline-button" class="p s" onclick="prepareOfflineScanner()" ${scannerOffline.busy?'disabled':''}>${scannerOffline.busy?T2('Preparing…','در حال آماده‌سازی…'):scannerOffline.ready?T2('Check offline scanner','بررسی اسکنر آفلاین'):T2('Prepare offline scanner','آماده‌سازی اسکن آفلاین')}</button></section>`}
