async function applyDateCheck(){const d=sc.dateCheck,p=sc.pages[d.pi],end=d.col+(d.count-1)*d.dr;if(end<0||end>=p.vl.length-1||Array.from({length:Math.abs(end-d.col)+1},(_,i)=>Math.min(d.col,end)+i).some(i=>scanNameOverlap(p,i)))return alert(T2('These dates reach outside the date columns. Check day 1 and the direction.','تاریخ‌ها از ستون‌های روزها خارج می‌شوند. ستون روز ۱ و جهت را بررسی کنید.'));const mapping=i=>{const day=1+(i-d.col)*d.dr;return day>=1&&day<=d.count?day:0},changed=p.vl.slice(0,-1).some((_,i)=>{const old=p.dayAt(i);return(old>=1&&old<=d.count?old:0)!==mapping(i)});p.dayAt=mapping;p.dr=d.dr;p.guess=false;p.datesConfirmed=true;sc.dateCheck=null;usePage(d.pi);if(Number.isInteger(sc.continueReadRow)){const row=sc.continueReadRow;sc.continueReadRow=null;sc.pick=false;sc.busy=true;render();return readCells(row)}if(sc.continueReadAll){sc.continueReadAll=false;return readAll()}if(sc.cells&&sc.rows[sc.ri]?.pi===d.pi&&changed){sc.continueImportAll=false;sc.busy=true;render();return readCells(sc.ri,true)}if(sc.continueImportAll){sc.continueImportAll=false;return doImport(true)}render()}
