function chooseRosterImportMonth(){const c=rosterImportChoice;if(!c)return;const d=new Date(c.dates[0]+'T00:00'),j=jp(d),year=S.cal==='j'?j.y:d.getFullYear(),month=S.cal==='j'?j.m:d.getMonth()+1;dlg(`<section class="import-month-choice"><h2>${T2('Which month is this roster for?','این برنامه برای کدوم ماهه؟')}</h2><label>${T2('Year','سال')}<input id="import-year" inputmode="numeric" dir="ltr" value="${year}"></label><label>${T2('Month','ماه')}<select id="import-month">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${month===i+1?'selected':''}>${S.cal==='j'?JM[i]:new Date(2026,i,1).toLocaleDateString(loc(),{month:'long'})}</option>`).join('')}</select></label><p id="import-month-error" role="alert"></p><div class="dialog-actions"><button class="p" onclick="applyRosterImportMonth()">${T2('Check this month','بررسی برنامهٔ این ماه')}</button><button class="p s" onclick="cancelRosterImportChoice()">${T2('Cancel','لغو')}</button></div></section>`)}
