function remapFileMonth(plan){if(!fi.dateOverride)return plan;const months=new Set(plan.dates.map(date=>{const d=new Date(date+'T00:00'),j=jp(d);return fi.dateOverride.calendar==='j'?j.y+'/'+j.m:d.getFullYear()+'/'+d.getMonth()}));if(months.size>1){plan.errors.push(T2('This file contains several months. Change its dates in the source file.','این فایل چند ماه دارد؛ تاریخ‌ها را در خود فایل اصلاح کن.'));return plan}const dates=Object.fromEntries(plan.dates.map(d=>[d,remapImportDate(d,fi.dateOverride)]));if(Object.values(dates).some(d=>!d)||new Set(Object.values(dates)).size!==plan.dates.length){plan.errors.push(T2('Some dates do not fit this month. Choose another month.','بعضی روزها در این ماه وجود ندارند؛ ماه دیگری انتخاب کن.'));return plan}plan.dates=Object.values(dates).sort();for(const p of plan.people)p.cells=Object.fromEntries(Object.entries(p.cells).map(([d,v])=>[dates[d],v]));return plan}
