function coverageNeeds(start,end){const first=iso(start),last=iso(Math.max(start,(end||start+DAY)-1)),out=[];for(const w of S.wps.filter(w=>w.active!==false)){const dates=[];for(let d=first,n=0;d<=last&&n<62;d=rosterDate(d,1),n++)if(!rosterKnownAt(w.id,d))dates.push(d);if(dates.length)out.push({wp:w.id,date:dates[0],count:dates.length})}return out}
