async function saveCover(hid,mid){if(tour.active)return;const x=coverChoice(hid,mid);if(!x)return alert(T2('The roster changed. Find suggestions again.','برنامه تغییر کرده؛ پیشنهادها را دوباره پیدا کن.'));const {h,m,w,choice}=x,off=offCode(w),text=choice.combo||h.text;if(!off)return;const codes=parse(w,text),issue=checkRosterChange(w,m,{[h.date]:{text,segs:makeSegs(h.date,codes||[])}},true);if(issue.kind!=='ok'){return alert(swapReason(issue)||T2('Review the surrounding roster dates first.','اول برنامهٔ روزهای اطراف را بررسی کن.'))}const change=beginChange('Shift handover','واگذاری شیفت',['shifts','mates','rosterDays','swapHistory']);const before={own:copyJSON(h),mate:m.cells[h.date]};Object.assign(h,{text:off,label:T2('Off','off'),segs:[],review:false});delete h.scan;m.cells[h.date]=text;m.uns=(m.uns||[]).filter(d=>d!==h.date);if(m.scan)delete m.scan[h.date];S.rosterDays[w.id+'|'+h.date]=true;S.swapHistory=[...(S.swapHistory||[]),{id:'cover'+Date.now(),kind:'handover',wp:w.id,mate:m.id,dates:[h.date],at:Date.now(),before,after:{own:off,mate:text}}].slice(-50);if(!await commitChange(change))return;closeDialog();tc.notice=T2('Handover saved with ','واگذاری ثبت شد با ')+colleagueDisplayName(m);tc.dates=[];tc.res=null;tab='team';render();window.scrollTo?.(0,0)}
