 const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1);for(let i=-31;i<94;i++){const date=iso(new Date(first.getFullYear(),first.getMonth(),first.getDate()+i));S.shifts.push({id:'sample'+date,wp:w.id,date,text:'-',segs:[],review:false});S.rosterDays[w.id+'|'+date]=true}
